// ═══ HOW SUPPRESSED EXCEPTIONS WORK ═══

// Scenario: try throws AND close() throws
try (AutoCloseable resource = () -> {
    throw new RuntimeException("CLOSE_FAILED: connection reset");
}) {
    throw new IllegalStateException("TRADE_FAILED: invalid exchange rate");
}

// RESULT:
// catch (Exception e) {
//   e → IllegalStateException("TRADE_FAILED")  ← PRIMARY (from try body)
//   e.getSuppressed()[0] → RuntimeException("CLOSE_FAILED")  ← SUPPRESSED (from close)
// }
// BOTH preserved! Nothing lost!

// ═══ ACCESSING SUPPRESSED EXCEPTIONS ═══
try {
    methodThatUsesResources();
} catch (Exception e) {
    log.error("Primary error: {}", e.getMessage());  // TRADE_FAILED
    for (Throwable suppressed : e.getSuppressed()) {
        log.warn("Suppressed: {}", suppressed.getMessage());  // CLOSE_FAILED
    }
    // Full stack trace includes suppressed:
    e.printStackTrace();
    // Output:
    // IllegalStateException: TRADE_FAILED
    //   at ...
    //   Suppressed: RuntimeException: CLOSE_FAILED
    //     at ...
}

// ═══ MULTIPLE suppressed (multiple resources) ═══
try (AutoCloseable r1 = () -> { throw new Exception("CLOSE_R1"); };
     AutoCloseable r2 = () -> { throw new Exception("CLOSE_R2"); }) {
    throw new RuntimeException("MAIN_ERROR");
}
// r2 closed first (reverse order) → "CLOSE_R2" suppressed
// r1 closed second → "CLOSE_R1" suppressed
// e.getSuppressed() = [CLOSE_R2, CLOSE_R1] — BOTH attached!

// ═══ MANUALLY adding suppressed exceptions ═══
public void processBatch(List<Trade> trades) {
    RuntimeException primary = null;
    for (Trade trade : trades) {
        try {
            settle(trade);
        } catch (RuntimeException e) {
            if (primary == null) {
                primary = e;  // first error = primary
            } else {
                primary.addSuppressed(e);  // subsequent errors = suppressed
            }
        }
    }
    if (primary != null) throw primary;
    // Caller sees: primary exception + ALL suppressed batch errors!
}
