package com.bank.suppressed.service;

import java.util.List;

public class BatchSettlementService {

    // ═══ Manual addSuppressed for batch processing ═══
    public void settleBatch(List<String> tradeIds) {
        RuntimeException primary = null;

        for (String tradeId : tradeIds) {
            try {
                settle(tradeId);
            } catch (RuntimeException e) {
                if (primary == null) {
                    primary = e;  // first failure = primary
                } else {
                    primary.addSuppressed(e);  // subsequent = suppressed
                }
            }
        }

        if (primary != null) {
            throw primary;  // contains ALL failures!
        }
    }

    private void settle(String tradeId) {
        if (tradeId.contains("FAIL")) {
            throw new RuntimeException("Settlement failed for " + tradeId);
        }
    }
}
