// ─── File: src/test/java/com/bank/suppressed/SuppressedExceptionTest.java ───
package com.bank.suppressed;

import com.bank.suppressed.service.BatchSettlementService;
import org.junit.jupiter.api.Test;
import java.util.List;
import static org.assertj.core.api.Assertions.*;

class SuppressedExceptionTest {

    // ═══ try-with-resources: close exception is SUPPRESSED ═══
    @Test
    void tryWithResources_closeExceptionSuppressed() {
        try {
            try (AutoCloseable res = () -> { throw new Exception("CLOSE"); }) {
                throw new RuntimeException("MAIN");
            }
        } catch (Exception e) {
            assertThat(e.getMessage()).isEqualTo("MAIN");            // PRIMARY
            assertThat(e.getSuppressed()).hasSize(1);
            assertThat(e.getSuppressed()[0].getMessage()).isEqualTo("CLOSE");  // SUPPRESSED
        }
    }

    // ═══ Multiple resources: multiple suppressed ═══
    @Test
    void multipleResources_multipleSuppressed() {
        try {
            try (AutoCloseable r1 = () -> { throw new Exception("CLOSE_1"); };
                 AutoCloseable r2 = () -> { throw new Exception("CLOSE_2"); }) {
                throw new RuntimeException("MAIN");
            }
        } catch (Exception e) {
            assertThat(e.getMessage()).isEqualTo("MAIN");
            assertThat(e.getSuppressed()).hasSize(2);  // BOTH close exceptions!
        }
    }

    // ═══ Only close throws (no try body exception) ═══
    @Test
    void onlyCloseThrows_becomePrimary() {
        assertThatThrownBy(() -> {
            try (AutoCloseable res = () -> { throw new Exception("CLOSE_ONLY"); }) {
                // try body succeeds — no exception
            }
        }).hasMessage("CLOSE_ONLY");
        // When only close() throws → IT becomes the primary. No suppressed.
    }

    // ═══ Manual addSuppressed in batch processing ═══
    @Test
    void batchProcessing_allFailuresVisible() {
        BatchSettlementService service = new BatchSettlementService();

        assertThatThrownBy(() -> service.settleBatch(
            List.of("TRD-OK-1", "TRD-FAIL-1", "TRD-OK-2", "TRD-FAIL-2", "TRD-FAIL-3")))
            .isInstanceOf(RuntimeException.class)
            .hasMessageContaining("FAIL-1")                    // primary = first failure
            .satisfies(e -> {
                assertThat(e.getSuppressed()).hasSize(2);       // 2 more failures
                assertThat(e.getSuppressed()[0].getMessage()).contains("FAIL-2");
                assertThat(e.getSuppressed()[1].getMessage()).contains("FAIL-3");
            });
        // ALL 3 failures visible: primary + 2 suppressed. Nothing lost!
    }

    // ═══ Pre-Java-7 finally: original exception LOST ═══
    @Test
    void preJava7_finallySwallowsOriginal() {
        try {
            try {
                throw new RuntimeException("ORIGINAL");
            } finally {
                throw new RuntimeException("FINALLY");  // SWALLOWS ORIGINAL!
            }
        } catch (RuntimeException e) {
            assertThat(e.getMessage()).isEqualTo("FINALLY");  // ORIGINAL is GONE!
            assertThat(e.getSuppressed()).isEmpty();           // no suppressed — truly lost!
        }
    }

    // ═══ Comparison: finally vs try-with-resources ═══
    @Test
    void comparison() {
        // Pre-Java-7 (finally throws):
        //   try throws "REAL_ERROR" + finally throws "CLOSE_ERROR"
        //   → caller sees: "CLOSE_ERROR". "REAL_ERROR" = GONE!

        // Java 7+ (try-with-resources):
        //   try throws "REAL_ERROR" + close() throws "CLOSE_ERROR"
        //   → caller sees: "REAL_ERROR" (primary) + "CLOSE_ERROR" (suppressed)
        //   → BOTH visible! Nothing lost!
        assertThat(true).isTrue();
    }
}
